function trier_tableau(arr) {
  let result = [...arr];
  // Implementation of Merge Sort for O(N log N) efficiency
  if (result.length <= 1) return result;

  const merge = (left, right) => {
    let sorted = [];
    let i = 0;
    let j = 0;
    while (i < left.length && j < right.length) {
      if (left[i] < right[j]) {
        sorted.push(left[i]);
        i++;
      } else {
        sorted.push(right[j]);
        j++;
      }
    }
    return sorted.concat(left.slice(i)).concat(right.slice(j));
  };

  const sort = (array) => {
    if (array.length <= 1) return array;
    const mid = Math.floor(array.length / 2);
    const left = sort(array.slice(0, mid));
    const right = sort(array.slice(mid));
    return merge(left, right);
  };

  return sort(result);
}
